drills.referenceSolution:
function starStory() {
  return {
    situation:
      'Our four-team platform group shipped behind one shared release train, and nearly a fifth of deploys ended in rollback. I was a senior engineer on one of those teams with no authority over the other three.',
    task:
      'Nobody owned the train itself. I wanted the rollback number down before the next planning cycle, which meant persuading three staff engineers who each believed the fault lived inside somebody else service.',
    action:
      'I spent two weeks pulling every rollback postmortem into one shared document and tagged each entry with a root cause instead of a team name. Then I ran a thirty minute review where each staff engineer picked the two causes they wanted to own. I wrote the migration guide for the pre deploy smoke suite myself, ported my own team first so the guide was proven, and published a weekly scoreboard so progress stayed visible without me chasing anybody. When one team stalled I paired with their on call engineer rather than escalating to their manager.',
    result:
      'Within a quarter the deploy failure rate fell from eighteen percent to 4 percent, and the scoreboard outlived my involvement because the platform group still publishes it every Monday.',
    metric: { name: 'deploy failure rate', unit: 'percent', before: 18, after: 4 },
    influenceTactic:
      'I traded ownership for visibility: every staff engineer chose which root cause to fix, and a public scoreboard did the chasing so I never had to.',
  };
}

