function starStory() {
  return {
    situation:
      'A peer and I disagreed publicly in a design review about whether our new service should own its data store or read through the existing monolith database that the billing team maintained.',
    task:
      'The review stalled twice and the team started routing around both of us. I needed a decision we could both defend afterwards, not a win, because we were going to share the on call rotation.',
    action:
      'I asked for a thirty minute call with no audience and opened by restating his position until he agreed I had it right. That took longer than I expected and changed my own view of the migration cost. We then wrote the two options into a shared document with the risks each of us actually feared, and agreed on a cheap experiment: shadow reads against a copy for two weeks. I let him present the results, since the data mostly supported his caution about migration timing rather than my preference.',
    result:
      'We shipped a read through adapter first and cut design review turnaround from thirty two hours to 6 hours because the disagreement stopped blocking the queue.',
    metric: { name: 'review turnaround', unit: 'hours', before: 32, after: 6 },
    theirCase:
      'He had absorbed two data migrations that slipped a quarter each, so his objection was about our track record on cutovers, not about service ownership as a principle.',
  };
}

