function starStory() {
  return {
    situation:
      'Checkout errors spiked the week before a seasonal peak and the traces pointed ambiguously at either a new payment provider or our own retry logic, with no clean way to tell them apart.',
    task:
      'I had to decide within a day whether to roll back the provider integration or keep it and patch our retries, knowing a rollback would burn the contract negotiation we had just finished.',
    action:
      'I wrote down both hypotheses with the evidence each one predicted, then looked for the cheapest discriminating measurement instead of arguing. We sampled failing requests by provider region and found errors clustered in one region only, which the retry hypothesis did not predict. That was thin evidence, so I kept the integration but shipped a circuit breaker scoped to that region and instrumented a per region success rate dashboard before going home. I told the room explicitly which observation would prove me wrong and what we would do the moment we saw it.',
    result:
      'Peak week held, and the checkout error rate came down from two point four percent to 0.3 percent without a rollback or a renegotiated contract.',
    metric: { name: 'checkout error rate', unit: 'percent', before: 2.4, after: 0.3 },
    earlyWarningSignal:
      'A per region success rate below ninety nine percent for fifteen minutes would have meant the provider was not the cause and I was wrong.',
  };
}

