      'She funded the rework instead of the capacity, and support escalations fell from forty five per week to 12 per week within two months.',
    metric: { name: 'support escalations', unit: 'per week', before: 45, after: 12 },
    analogy:
      'More cars do not help when every car still has to pass through one toll booth, and our ledger table was the toll booth.',
  };
}

