function pushCount(n) {
  let cap = 1, size = 0, copies = 0;
  for (let i = 0; i < n; i++) {
    if (size === cap) { copies += size; cap *= 2; }
    size++;
  }
  return copies;
}

function sortByScore(rows) {
  return rows
    .map((row, index) => ({ row, index }))
    .sort((a, b) => b.row.score - a.row.score || a.index - b.index)
    .map((entry) => entry.row);
}

function size(dau, writesPerUserPerDay, bytesPerWrite, replicationFactor, peakMultiplier) {
  const writesPerDay = dau * writesPerUserPerDay;
  const writesPerSecond = writesPerDay / 86400;
  const bytesPerDay = writesPerDay * bytesPerWrite * replicationFactor;
  return {
    writesPerSecond: Math.round(writesPerSecond),
    peakWritesPerSecond: Math.round(writesPerSecond * peakMultiplier),
    storagePerDayGB: Math.round(bytesPerDay / 1e9),
    storagePerYearTB: Math.round((bytesPerDay * 365) / 1e12),
  };
}

const NON_FUNCTIONAL = /latency|availab|throughput|durab|consisten|outnumber|daily active|survive|scale|cost|encrypt|p9\d/i;

function classify(requirements) {
  const functional = [];
  const nonFunctional = [];
  for (const requirement of requirements) {
    (NON_FUNCTIONAL.test(requirement) ? nonFunctional : functional).push(requirement);
  }
  return { functional, nonFunctional };
}

function makeRangeSum(nums) {
  const prefix = new Array(nums.length + 1).fill(0);
  for (let i = 0; i < nums.length; i++) prefix[i + 1] = prefix[i] + nums[i];
  return (i, j) => prefix[j + 1] - prefix[i];
}

function nextGreater(nums) {
  const result = new Array(nums.length).fill(-1);
  const stack = [];
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[i] > nums[stack[stack.length - 1]]) {
      result[stack.pop()] = nums[i];
    }
    stack.push(i);
  }
  return result;
}

function findAll(text, pattern) {
  const n = text.length, m = pattern.length;
  const out = [];
  if (m === 0 || m > n) return out;
  const BASE = 256n, MOD = 1000000007n;
  let high = 1n;
  for (let i = 0; i < m - 1; i++) high = (high * BASE) % MOD;
  let ph = 0n, th = 0n;
  for (let i = 0; i < m; i++) {
    ph = (ph * BASE + BigInt(pattern.charCodeAt(i))) % MOD;
    th = (th * BASE + BigInt(text.charCodeAt(i))) % MOD;
  }
  for (let i = 0; i + m <= n; i++) {
    if (ph === th && text.slice(i, i + m) === pattern) out.push(i);
    if (i + m < n) {
      th = (th - BigInt(text.charCodeAt(i)) * high % MOD + MOD) % MOD;
      th = (th * BASE + BigInt(text.charCodeAt(i + m))) % MOD;
    }
  }
  return out;
}

function mstWeight(n, edges) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  let total = 0, used = 0;
  for (const [u, v, w] of [...edges].sort((a, b) => a[2] - b[2])) {
    const ru = find(u), rv = find(v);
    if (ru === rv) continue;
    parent[ru] = rv;
    total += w;
    used++;
  }
  return used === n - 1 ? total : -1;
}

function wouldSkew(t1, t2) {
  const r1 = new Set(t1.reads), r2 = new Set(t2.reads);
  const w1 = new Set(t1.writes), w2 = new Set(t2.writes);
  const readsOverlap = [...r1].some((k) => r2.has(k));
  const writesDisjoint = ![...w1].some((k) => w2.has(k));
  const crossWrite = [...w1].some((k) => r2.has(k)) || [...w2].some((k) => r1.has(k));
  return readsOverlap && writesDisjoint && crossWrite;
}

function chooseJoin(p) {
  if (p.leftSorted && p.rightSorted) return 'merge';
  const smaller = Math.min(p.leftRows, p.rightRows);
  if (smaller > p.memoryRows) return 'merge';
  if (p.hasIndexOnRight && p.leftRows <= 100) return 'nested-loop';
  return 'hash';
}

function backoffDelays(attempts, baseMs, capMs, rand) {
  const out = [];
  for (let i = 0; i < attempts; i++) {
    const ceiling = Math.min(capMs, baseMs * 2 ** i);
    out.push(Math.floor(rand() * ceiling));
  }
  return out;
}

function buildQuery(table, filters) {
  const keys = Object.keys(filters);
  const values = [];
  const clauses = keys.map((key, i) => {
    if (!ALLOWED.has(key)) throw new Error(`disallowed column: ${key}`);
    values.push(filters[key]);
    return `${key} = $${i + 1}`;
  });
  return { text: `SELECT * FROM ${table} WHERE ${clauses.join(' AND ')}`, values };
}

function mm1(lambdaRate, muRate) {
  if (lambdaRate >= muRate) return null;
  const rho = lambdaRate / muRate;
  const round = (x, d) => Math.round(x * 10 ** d) / 10 ** d;
  return {
    rho: round(rho, 2),
    avgInSystem: round(rho / (1 - rho), 2),
    avgWaitSeconds: round(1 / (muRate - lambdaRate), 4),
  };
}

function contrast(points, query) {
  const dist = (p) => Math.sqrt(p.reduce((s, v, i) => s + (v - query[i]) ** 2, 0));
  const ds = points.map(dist);
  const min = Math.min(...ds), max = Math.max(...ds);
  if (min === 0) return 0;
  return Math.round(((max - min) / min) * 1000) / 1000;
}

function prune(docs, upperBounds, k) {
  const heap = [];
  let scored = 0;
  for (const doc of docs) {
    const threshold = heap.length >= k ? heap[heap.length - 1].score : 0;
    const bound = doc.terms.reduce((s, t) => s + (upperBounds[t] ?? 0), 0);
    if (heap.length >= k && bound <= threshold) continue;
    scored++;
    heap.push(doc);
    heap.sort((a, b) => b.score - a.score);
    if (heap.length > k) heap.pop();
  }
  return { top: heap.map((d) => d.id), scored };
}

function makeLimiter(capacity, refillPerSecond) {
  let tokens = capacity;
  let last = null;
  return (nowMs) => {
    if (last === null) last = nowMs;
    tokens = Math.min(capacity, tokens + ((nowMs - last) / 1000) * refillPerSecond);
    last = nowMs;
    if (tokens >= 1) { tokens -= 1; return true; }
    return false;
  };
}

function pack(timestampMs, machineId, sequence) {
  if (machineId > 1023n || machineId < 0n) throw new Error('machineId out of range');
  if (sequence > 4095n || sequence < 0n) throw new Error('sequence out of range');
  return (BigInt(timestampMs) << 22n) | (BigInt(machineId) << 12n) | BigInt(sequence);
}

function unpack(id) {
  return {
    timestampMs: BigInt(id) >> 22n,
    machineId: (BigInt(id) >> 12n) & 1023n,
    sequence: BigInt(id) & 4095n,
  };
}

function masterCase(a, b, fExp) {
  const c = Math.log(a) / Math.log(b);
  if (Math.abs(fExp - c) < 1e-9) return 'balanced';
  return fExp < c ? 'leaves' : 'root';
}

function kthSmallest(nums, k) {
  const arr = [...nums];
  let lo = 0, hi = arr.length - 1, target = k - 1;
  while (lo < hi) {
    const pivot = arr[lo + Math.floor(Math.random() * (hi - lo + 1))];
    let i = lo, lt = lo, gt = hi;
    while (i <= gt) {
      if (arr[i] < pivot) { [arr[i], arr[lt]] = [arr[lt], arr[i]]; i++; lt++; }
      else if (arr[i] > pivot) { [arr[i], arr[gt]] = [arr[gt], arr[i]]; gt--; }
      else i++;
    }
    if (target < lt) hi = lt - 1;
    else if (target > gt) lo = gt + 1;
    else return pivot;
  }
  return arr[lo];
}

function violatesThirdNF(columns, key, dependencies) {
  const keySet = new Set(key);
  return dependencies.some((d) => {
    const isSuperkey = key.every((k) => d.determinant.includes(k));
    const dependentInKey = keySet.has(d.dependent);
    return !isSuperkey && !dependentInKey;
  });
}

function simulate(capacity, accesses, policy) {
  const resident = new Map();
  const counts = new Map();
  let hits = 0, clock = 0;
  for (const page of accesses) {
    clock++;
    counts.set(page, (counts.get(page) ?? 0) + 1);
    if (resident.has(page)) { hits++; resident.set(page, clock); continue; }
    if (resident.size >= capacity) {
      const entries = [...resident.entries()];
      const hot = (p) => (policy === 'lru2' ? (counts.get(p) ?? 0) >= 2 : true);
      const cold = entries.filter(([p]) => !hot(p));
      const pool = cold.length ? cold : entries;
      pool.sort((x, y) => x[1] - y[1]);
      resident.delete(pool[0][0]);
    }
    resident.set(page, clock);
  }
  return hits;
}

function page(rows, cursor, limit) {
  const after = (r) =>
    !cursor || r.createdAt > cursor.createdAt || (r.createdAt === cursor.createdAt && r.id > cursor.id);
  const items = rows.filter(after).slice(0, limit);
  const nextCursor =
    items.length === limit
      ? { createdAt: items[items.length - 1].createdAt, id: items[items.length - 1].id }
      : null;
  return { items, nextCursor };
}

function countDivisible(n, divisors) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  let total = 0;
  for (let mask = 1; mask < 1 << divisors.length; mask++) {
    let l = 1, bits = 0;
    for (let i = 0; i < divisors.length; i++) {
      if (mask & (1 << i)) { l = (l * divisors[i]) / gcd(l, divisors[i]); bits++; }
    }
    total += (bits % 2 === 1 ? 1 : -1) * Math.floor(n / l);
  }
  return total;
}

function logSumExp(xs) {
  const m = Math.max(...xs);
  if (!Number.isFinite(m)) return m;
  let sum = 0;
  for (const x of xs) sum += Math.exp(x - m);
  return m + Math.log(sum);
}

function ndcgAtK(relevances, k) {
  const dcg = (arr) =>
    arr.slice(0, k).reduce((s, rel, i) => s + rel / Math.log2(i + 2), 0);
  const ideal = dcg([...relevances].sort((a, b) => b - a));
  if (ideal === 0) return 0;
  return Math.round((dcg(relevances) / ideal) * 10000) / 10000;
}

function debiasedCtr(events, propensity) {
  const acc = {};
  for (const e of events) {
    acc[e.docId] ??= { weighted: 0, impressions: 0 };
    acc[e.docId].impressions++;
    if (e.clicked) acc[e.docId].weighted += 1 / propensity[e.position];
  }
  const out = {};
  for (const [id, v] of Object.entries(acc)) {
    out[id] = Math.round((v.weighted / v.impressions) * 10000) / 10000;
  }
  return out;
}

function quantize(vec, min, max) {
  const width = (max - min) / 255;
  return vec.map((x) => {
    const c = Math.round((Math.min(max, Math.max(min, x)) - min) / width);
    return Math.min(255, Math.max(0, c));
  });
}

function dequantize(codes, min, max) {
  const width = (max - min) / 255;
  return codes.map((c) => min + c * width);
}

function maxAbsError(vec, min, max) {
  const back = dequantize(quantize(vec, min, max), min, max);
  return Math.max(...vec.map((x, i) => Math.abs(Math.min(max, Math.max(min, x)) - back[i])));
}

function queryCost({ hops, neighboursPerHop, cachedFraction, readLatencyUs, compareLatencyNs }) {
  const fetched = hops * neighboursPerHop;
  const randomReads = fetched * (1 - cachedFraction);
  const totalUs = randomReads * readLatencyUs + (fetched * compareLatencyNs) / 1000;
  const r2 = (x) => Math.round(x * 100) / 100;
  return { randomReads: r2(randomReads), totalUs: r2(totalUs) };
}

function search(graph, deleted, entry, query, k, budget) {
  const seen = new Set();
  const queue = [entry];
  const found = [];
  let visited = 0;
  while (queue.length && visited < budget) {
    const id = queue.shift();
    if (seen.has(id) || !graph[id]) continue;
    seen.add(id);
    visited++;
    if (!deleted.has(id)) found.push(id);
    for (const n of graph[id].n) if (!seen.has(n)) queue.push(n);
  }
  return found
    .sort((a, b) => Math.abs(graph[a].v - query) - Math.abs(graph[b].v - query))
    .slice(0, k);
}

function edgePolicy({ url, hasAuthCookie, varyHeaders, contentHashed }) {
  const key = [url, ...varyHeaders].join('|');
  if (hasAuthCookie) return { cacheable: false, ttlSeconds: 0, key };
  return { cacheable: true, ttlSeconds: contentHashed ? 31536000 : 300, key };
}
